package com.lbos.commercecustomer.repository; import com.lbos.commercecustomer.entity.*;import java.util.*;import org.springframework.data.domain.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param; public interface ProductRepository extends JpaRepository<Product,Long>,org.springframework.data.jpa.repository.JpaSpecificationExecutor<Product> {Optional<Product> findByIdAndRetailerId(Long id,UUID retailerId); /** The retailer's own products for a set of upper-cased SKUs, with category, in ONE query - bulk upload uses this instead of one lookup per row. */ @Query("select p from Product p join fetch p.category where p.retailerId=:retailerId and upper(p.sku) in :skus") List<Product> findWithCategoryByRetailerIdAndSkuIn(@Param("retailerId") UUID retailerId,@Param("skus") Collection<String> skus); boolean existsByRetailerIdAndSkuIgnoreCase(UUID retailerId,String sku); boolean existsByRetailerIdAndSkuIgnoreCaseAndIdNot(UUID retailerId,String sku,Long id); Page<Product> findByRetailerId(UUID id,Pageable p); List<Product> findByIdIn(Collection<Long> ids); /** Category id of every given product in ONE query - checkout uses it to tell S6 which tax category each line belongs to. */ @Query("select new com.lbos.commercecustomer.repository.ProductCategoryRef(p.id, p.category.id) from Product p where p.id in :ids") List<ProductCategoryRef> findCategoryRefsByProductIds(@Param("ids") Collection<Long> ids); @Modifying @Query("update Product p set p.stock=p.stock+:q where p.id=:id and p.retailerId=:r") int addStock(@Param("id") Long id,@Param("r") UUID r,@Param("q") int q); @Modifying @Query("update Product p set p.stock=p.stock-:q where p.id=:id and p.retailerId=:r and p.stock>=:q") int removeStock(@Param("id") Long id,@Param("r") UUID r,@Param("q") int q); @Modifying @Query("update Product p set p.stock=p.stock+:q where p.id=:id") int addStock(@Param("id") Long id,@Param("q") int q); @Modifying @Query("update Product p set p.stock=p.stock-:q where p.id=:id and p.stock>=:q") int removeStock(@Param("id") Long id,@Param("q") int q);}